package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.*;
import com.ruoyi.medical.workflow.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.time.Duration;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.professional-runtime.document-review-enabled",havingValue="true",matchIfMissing=false)
public class DocumentReviewRuntimeConfiguration {
 @Bean DocumentReviewDeployment documentReviewDeployment(@Value("${medical.professional-runtime.document-review.deployment-file}")Path file,@Value("${medical.professional-runtime.document-review.deployment-owner}")String owner,@Value("${medical.professional-runtime.document-review.deployment-sha256}")String hash,@Value("${medical.professional-runtime.document-review.maximum-deployment-bytes}")int maximum)throws Exception{return readDeployment(file,owner,hash,maximum);}
    static DocumentReviewDeployment readDeployment(Path file,String owner,String expected,int maximum)throws Exception {
        if(file==null||!file.isAbsolute()||!file.normalize().equals(file)||owner==null||owner.isBlank()||maximum<1||maximum>2097152||!file.toRealPath().equals(file))throw new IllegalArgumentException("PINNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var principal=file.getFileSystem().getUserPrincipalLookupService().lookupPrincipalByName(owner);
        var before=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(!before.isRegularFile()||before.size()<1||before.size()>maximum||!Files.getOwner(file,LinkOption.NOFOLLOW_LINKS).equals(principal))throw new IllegalArgumentException("OWNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var permissions=Files.getPosixFilePermissions(file,LinkOption.NOFOLLOW_LINKS);if(!Set.of(PosixFilePermissions.fromString("r--------"),PosixFilePermissions.fromString("rw-------")).contains(permissions))throw new IllegalArgumentException("PRIVATE_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        byte[] bytes;try(var input=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){bytes=input.readNBytes(maximum+1);}var after=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(bytes.length!=before.size()||bytes.length>maximum||!Objects.equals(before.fileKey(),after.fileKey())||!before.lastModifiedTime().equals(after.lastModifiedTime())||before.size()!=after.size())throw new IllegalArgumentException("PROFESSIONAL_DEPLOYMENT_CHANGED");
        var json=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
        return new DocumentReviewDeployment(json.readTree(bytes),expected);
    }

 @Bean DocumentReviewJobAuthority documentReviewJobAuthority(DocumentReviewExecutionService jobs){return new DocumentReviewJobAuthority(jobs);}
 @Bean DocumentReviewControlAccess documentReviewControlAccess(@Qualifier("masterDataSource")DataSource data,TenantTransaction tx,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services,PermissionMapper permissions,PermissionAuthority grants,DocumentReviewExecutionService jobs,RunTokenAuthoritySchema tokens,@Value("${medical.professional-runtime.document-review.maximum-control-seconds}")long seconds,DocumentReviewDeployment deployment,VersionResourceMapper owners,ArtifactRegistryMapper registry){return new DocumentReviewControlAccess(data,tx,services,permissions,grants,jobs,tokens,Duration.ofSeconds(seconds),deployment,owners,registry);}
 @Bean DocumentReviewRuntimeAuthority documentReviewRuntimeAuthority(@Qualifier("masterDataSource")DataSource data,DocumentReviewExecutionService jobs,RunTokenAuthoritySchema tokens,FormalCapabilityIdentityAuthority roles){return new DocumentReviewRuntimeAuthority(data,jobs,new TaskSourceVerifierSchema(),tokens,roles);}
 @Bean DocumentReviewTokenAuthority documentReviewTokenAuthority(@Qualifier("masterDataSource")DataSource data,DocumentReviewControlAccess controls,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,DocumentReviewAdmission admissions,DocumentReviewJobAuthority jobs,DocumentReviewExecutionService executions,DocumentReviewRuntimeAuthority runtime,DocumentReviewAuthority documents){return new DocumentReviewTokenAuthority(data,controls,publications,policies,admissions,jobs,executions,new TaskSourceVerifierSchema(),runtime,documents);}
 @Bean DocumentReviewWorkerAccess documentReviewWorkerAccess(FormalWorkerAccess workers,RunTokenAuthority tokens){return new DocumentReviewWorkerAccess(workers,tokens);}
 @Bean DocumentReviewPromptCompiler documentReviewPromptCompiler(FormalCapabilityIdentityAuthority capabilities,PermissionSchema json,DocumentReviewExecutionService executions)throws Exception{return new DocumentReviewPromptCompiler(capabilities,json,executions);}
 @Bean DocumentReviewContextReads documentReviewContextReads(@Qualifier("masterDataSource")DataSource data,SourceUploadTransport transport,SourceReadAuthority sources,TaskFieldSourceAuthority processing,TaskResearchSourceReader literals,PermissionSchema json,DependencyLineage lineage,EvaluationDependencyPolicy limits,VersionResourceMapper owners){return new DocumentReviewContextReads(data,transport,sources,processing,literals,json,lineage,limits,owners);}
 @Bean DocumentReviewRuntimeAdapter documentReviewRuntimeAdapter(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,DocumentReviewDeployment deployment,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,DocumentReviewExecutionService executions){return new DocumentReviewRuntimeAdapter(data,new TaskSourceVerifierSchema(),json,deployment,identities,executions);}
 @Bean DocumentReviewSupervisor documentReviewSupervisor(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,@Qualifier("documentReviewSupervisorTrust")ServiceCertificateIdentity.TrustSource trust,@Qualifier("documentReviewSupervisorTls")ServiceClientTlsStore.ContextSource tls){return new DocumentReviewSupervisor(data,json,new ServiceCertificateIdentity(trust),trust,tls);}
 @Bean DocumentReviewHostAccess documentReviewHostAccess(DocumentReviewControlAccess controls,DocumentReviewWorkerAccess workers,DocumentReviewRuntimeAuthority authorities,TaskInvocationPackages packages,DocumentReviewPromptCompiler compiler,DocumentReviewRuntimeAdapter runtime,DocumentReviewDeployment deployment,RunTokenAuthority tokens,DocumentReviewContextReads reads){return new DocumentReviewHostAccess(controls,workers,authorities,packages,compiler,runtime,deployment,tokens,reads);}
 @Bean DocumentReviewHostOrchestrator documentReviewHostOrchestrator(DocumentReviewRuntimeAdapter runtime,DocumentReviewSupervisor supervisor){return new DocumentReviewHostOrchestrator(runtime,supervisor);}
 @Bean DocumentReviewHostBootstrap documentReviewHostBootstrap(@Qualifier("masterDataSource")DataSource data,DocumentReviewControlAccess controls,DocumentReviewLaunchLedger launches,RunTokenAuthority tokens,DocumentReviewHostAccess hosts,DocumentReviewDeployment deployment,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services){return new DocumentReviewHostBootstrap(data,controls,launches,tokens,hosts,deployment,services);}
 @Bean DocumentReviewSupervisorGate documentReviewSupervisorGate(@Qualifier("masterDataSource")DataSource data,DocumentReviewControlAccess controls,DocumentReviewExecutionService jobs,DocumentReviewAdmission admissions,DocumentReviewJobAuthority authority,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,DocumentReviewRuntimeAuthority runtime,DocumentReviewDeployment deployment,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services,TaskInvocationPackages packages,DocumentReviewAuthority documents,DocumentReviewContextReads reads){return new DocumentReviewSupervisorGate(data,controls,jobs,admissions,authority,publications,policies,runtime,deployment,services,new TaskSourceVerifierSchema(),packages,documents,reads);}
 @Bean DocumentReviewRuntimeObservations documentReviewRuntimeObservations(@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,TenantTransaction transactions,@Qualifier("masterDataSource")DataSource data,PermissionSchema json){return new DocumentReviewRuntimeObservations(identities,transactions,data,json);}
 @Bean DocumentReviewResultService documentReviewResultService(@Qualifier("masterDataSource")DataSource data,ResourceReadAuthority resources,DocumentReviewInvocationService invocations,DocumentReadService documents)throws Exception{return new DocumentReviewResultService(data,resources,invocations,documents);}
 @Bean DocumentReviewObjectLedger documentReviewObjectLedger(@Qualifier("masterDataSource")DataSource data,DependencyManifestSchema dependencies)throws Exception{return new DocumentReviewObjectLedger(data,dependencies);}
 @Bean(name="documentReviewResultTransport")RuntimeObjectTransport documentReviewResultTransport(SourceUploadTransport objects,DocumentReviewDeployment deployment,@Value("${medical.professional-runtime.document-review.object-directory}")Path directory)throws Exception{return new RuntimeObjectTransport(objects,directory,deployment.maximumBytes());}
 @Bean DocumentReviewFinishOrchestrator documentReviewFinishOrchestrator(DocumentReviewRuntimeAdapter runtime,DocumentReviewSupervisor supervisor,DocumentReviewInvocationService invocations,DocumentReviewObjectLedger objects,@Qualifier("documentReviewResultTransport")RuntimeObjectTransport transport,DocumentReviewResultService results,DocumentReviewCompletionLedger completions){return new DocumentReviewFinishOrchestrator(runtime,supervisor,invocations,objects,transport,results,completions);}
}
